(837021, 94743, 8054, '<td valign="top">Busy composition with all the pinheads but it works well. My grandmother''s pin cushion literally had no room left for another pin. Nice sharp details where they count and colors are excellent. 10</td>', 'Busy composition with all the pinheads but it works well. My grandmother''s pin cushion literally had no room left for another pin. Nice sharp details where they count and colors are excellent. 10', '2004-08-02 11:18:45.000000', NULL, 1),
(837024, 95232, 8054, '<td valign="top">Excellent DOF and it''s very well done. Nice muted colors all around. 10</td>', 'Excellent DOF and it''s very well done. Nice muted colors all around. 10', '2004-08-02 11:22:07.000000', NULL, 1),
(837028, 94328, 8054, '<td valign="top">The left side seems very over exposed but the right 2/3s seem fine. Nice desat, too.</td>', 'The left side seems very over exposed but the right 2/3s seem fine. Nice desat, too.', '2004-08-02 11:23:27.000000', NULL, 1),
(837033, 94865, 8054, '<td valign="top">Interesting angle on a computer expansion card. Maybe show more of the card and less of the edge next time. That will give the feeling of a landscape. The border is a bit distracting.</td>', 'Interesting angle on a computer expansion card. Maybe show more of the card and less of the edge next time. That will give the feeling of a landscape. The border is a bit distracting.', '2004-08-02 11:27:53.000000', NULL, 1),
(837062, 95147, 19982, '<td valign="top">I gave a good score, but I think just a little more sharpness and it woulda been great!</td>', 'I gave a good score, but I think just a little more sharpness and it woulda been great!', '2004-08-02 12:05:01.000000', NULL, 1),
(837069, 93891, 13136, '<td valign="top">Good shot. There is no context to make me think this is anything more than a life-size face mask. However, I will vote assuming that it really is a macro.</td>', 'Good shot. There is no context to make me think this is anything more than a life-size face mask. However, I will vote assuming that it really is a macro.', '2004-08-02 12:15:35.000000', NULL, 1),
(837070, 94163, 13136, '<td valign="top">The background is a bit overblown and the center of the flower too dark.</td>', 'The background is a bit overblown and the center of the flower too dark.', '2004-08-02 12:16:56.000000', NULL, 1),
(837082, 94329, 19978, '<td valign="top">I like the title and an interesting picture</td>', 'I like the title and an interesting picture', '2004-08-02 12:26:54.000000', NULL, 1),
(837083, 94121, 24454, '<td valign="top">Beautiful color and sharpness!</td>', 'Beautiful color and sharpness!', '2004-08-02 12:27:09.000000', NULL, 1),
(837084, 94076, 16917, '<td valign="top">really lovely ocmposition</td>', 'really lovely ocmposition', '2004-08-02 12:27:35.000000', NULL, 1),
(837085, 93870, 24454, '<td valign="top">THAT is a cool shot!</td>', 'THAT is a cool shot!', '2004-08-02 12:28:05.000000', NULL, 1),
(837086, 95042, 19737, '<td valign="top">Nice shot, not a macrom in my opinion</td>', 'Nice shot, not a macrom in my opinion', '2004-08-02 12:28:38.000000', NULL, 1),
(837087, 94785, 16917, '<td valign="top">i do like this pic and I know you can''t stage these things, but the spider seems to be getting a bit lost with its prey in the web.i''m just wondering if there was another angle to try ot shoot this from. If only you could have asked it to climb a big higher so it would be on its own, and look at the camera!</td>', 'i do like this pic and I know you can''t stage these things, but the spider seems to be getting a bit lost with its prey in the web.i''m just wondering if there was another angle to try ot shoot this from. If only you could have asked it to climb a big higher so it would be on its own, and look at the camera!', '2004-08-02 12:30:12.000000', NULL, 1),
(837088, 94465, 19737, '<td valign="top">nice sharpness</td>', 'nice sharpness', '2004-08-02 12:32:36.000000', NULL, 1);
