(837506, 94655, 22734, '<td valign="top">Killer shot. You get a solid 6.</td>', 'Killer shot. You get a solid 6.', '2004-08-02 16:19:09.000000', NULL, 1),
(837508, 95132, 19608, '<td valign="top">Nose-to-nose look~  focus is perfect on the eye which is good.  The white base looks like snow which seems a bit unnatural for the snake.  Exposure appears right on.</td>', 'Nose-to-nose look~  focus is perfect on the eye which is good.  The white base looks like snow which seems a bit unnatural for the snake.  Exposure appears right on.', '2004-08-02 16:20:10.000000', NULL, 1),
(837511, 94240, 19608, '<td valign="top">A great spider - too bad his web is in such disarray.  The white streaks in the background detract a bit.  The smaller spider adds a pop of interest.</td>', 'A great spider - too bad his web is in such disarray.  The white streaks in the background detract a bit.  The smaller spider adds a pop of interest.', '2004-08-02 16:21:32.000000', NULL, 1),
