(837516, 94636, 4008, '<td valign="top">Cute. Great use of depth of field. I would probably crop just a tiny bit from the top, feels more balanced to me.</td>', 'Cute. Great use of depth of field. I would probably crop just a tiny bit from the top, feels more balanced to me.', '2004-08-02 16:22:27.000000', NULL, 1),
(837521, 94456, 4008, '<td valign="top">Should you not have rotated it 90 degrees ?</td>', 'Should you not have rotated it 90 degrees ?', '2004-08-02 16:23:08.000000', NULL, 1),
(837522, 95074, 19608, '<td valign="top">Good close-up with nice but maybe oversaturated colors.  Focus is right on where it should be.  In this case a dead-centered composition works well.</td>', 'Good close-up with nice but maybe oversaturated colors.  Focus is right on where it should be.  In this case a dead-centered composition works well.', '2004-08-02 16:23:46.000000', NULL, 1),
(837524, 95118, 4008, '<td valign="top">no focus ?</td>', 'no focus ?', '2004-08-02 16:24:04.000000', NULL, 1),
(837527, 94196, 19608, '<td valign="top">Good idea - it works pretty well except for the glares on the instrument.  Softer lighting would most likely make it more pleasing.  Excellent focus on the strings.</td>', 'Good idea - it works pretty well except for the glares on the instrument.  Softer lighting would most likely make it more pleasing.  Excellent focus on the strings.', '2004-08-02 16:25:09.000000', NULL, 1),
(837529, 95009, 22661, '<td valign="top">Great picture with full details of B</td>', 'Great picture with full details of B', '2004-08-02 16:25:58.000000', NULL, 1),
(837530, 94512, 4008, '<td valign="top">I don''t particularly like the angle of view. A great looking animal which should offer manu better possibilities.</td>', 'I don''t particularly like the angle of view. A great looking animal which should offer manu better possibilities.', '2004-08-02 16:26:15.000000', NULL, 1),
(837531, 94980, 19608, '<td valign="top">Excellent composition, lighting and exposure.  The problem is that there is no way to know for sure how close-up it is.  It could be "just" an excellent non-macro shot.  But, I will assume it really is macro and vote accordingly.  Good job.</td>', 'Excellent composition, lighting and exposure.  The problem is that there is no way to know for sure how close-up it is.  It could be "just" an excellent non-macro shot.  But, I will assume it really is macro and vote accordingly.  Good job.', '2004-08-02 16:27:07.000000', NULL, 1),
(837537, 94355, 4008, '<td valign="top">Since you have cut across the right hand border anyway I would have gone further and cut crop even more to the left and from the top, make it more focussing on the spiral, not on the total shape.</td>', 'Since you have cut across the right hand border anyway I would have gone further and cut crop even more to the left and from the top, make it more focussing on the spiral, not on the total shape.', '2004-08-02 16:29:07.000000', NULL, 1),
(837538, 94793, 19608, '<td valign="top">Very interseting idea - nice colors, lighting.  I''d like to see the bright "circle" - the most obvious center af attention - offset from the center a bit more.  Your shot borders on the rule of taking photos of someone else''s artwork.</td>', 'Very interseting idea - nice colors, lighting.  I''d like to see the bright "circle" - the most obvious center af attention - offset from the center a bit more.  Your shot borders on the rule of taking photos of someone else''s artwork.', '2004-08-02 16:29:24.000000', NULL, 1),
