(839005, 94531, 21714, '<td valign="top">Great detail, nice composition, DOF &amp;  lighting.  Well done.</td>', 'Great detail, nice composition, DOF &  lighting.  Well done.', '2004-08-03 10:59:51.000000', NULL, 1),
(839008, 95314, 21714, '<td valign="top">Excellent detail. Love the colours &amp; format of this image. Well done.</td>', 'Excellent detail. Love the colours & format of this image. Well done.', '2004-08-03 11:01:02.000000', NULL, 1),
(839012, 95343, 21714, '<td valign="top">Love this shot.  Wonderful colours and texture. Great detail &amp; well composed. Very well done. Would love to see this printed on canvas.</td>', 'Love this shot.  Wonderful colours and texture. Great detail & well composed. Very well done. Would love to see this printed on canvas.', '2004-08-03 11:03:03.000000', NULL, 1),
(839029, 94592, 15891, '<td valign="top">Nice detail in the petals! I would be interested to see what this photo would look like with a tighter crop across the top - the green in the BG is a little distracting.</td>', 'Nice detail in the petals! I would be interested to see what this photo would look like with a tighter crop across the top - the green in the BG is a little distracting.', '2004-08-03 11:11:32.000000', NULL, 1),
(839039, 94196, 21714, '<td valign="top">Good focus and composition. There''s a nice flow to this image. The reflections on the cello are not easy on the eye and they destroy this image. This would have been a beautiful image if the lights were better controlled. I suggest using diffusers and reflectors. It would soften the overall lights falling on the subject and will reduce the harsh highlights. Also the way it is now, it would be worth trying some desaturation on this shot. Try decreasing saturation on red, blue and magenta (maybe some yellow too).<br/>Anyway, I am suggesting all this because I do see potential in this shot and I do think that you can achieve much better results from the same composition.<br/>Good luck.</td>', 'Good focus and composition. There''s a nice flow to this image. The reflections on the cello are not easy on the eye and they destroy this image. This would have been a beautiful image if the lights were better controlled. I suggest using diffusers and reflectors. It would soften the overall lights falling on the subject and will reduce the harsh highlights. Also the way it is now, it would be worth trying some desaturation on this shot. Try decreasing saturation on red, blue and magenta (maybe some yellow too).Anyway, I am suggesting all this because I do see potential in this shot and I do think that you can achieve much better results from the same composition.Good luck.', '2004-08-03 11:15:49.000000', NULL, 1),
(839046, 95326, 21714, '<td valign="top">Nice saturated blue. Great composition. Well done.</td>', 'Nice saturated blue. Great composition. Well done.', '2004-08-03 11:17:15.000000', NULL, 1),
(839081, 95269, 19608, '<td valign="top">Absolute perfect focus and stunning  detail.  Three light sources?  The extra wide two-tone border doesn''t work for me.  Althoough this is probably a common choice for macro - it should do very well indeed.</td>', 'Absolute perfect focus and stunning  detail.  Three light sources?  The extra wide two-tone border doesn''t work for me.  Althoough this is probably a common choice for macro - it should do very well indeed.', '2004-08-03 11:34:30.000000', NULL, 1),
(839088, 94791, 19608, '<td valign="top">Nice seeing to notice the lip-shaped curl!  Nice focus on the "lips" and nice exposure.  DoF is as goon as you could expect with macro.</td>', 'Nice seeing to notice the lip-shaped curl!  Nice focus on the "lips" and nice exposure.  DoF is as goon as you could expect with macro.', '2004-08-03 11:37:00.000000', NULL, 1),
(839111, 94930, 16151, '<td valign="top">This eye looks wierd!  What type of animal is this? Horse?</td>', 'This eye looks wierd!  What type of animal is this? Horse?', '2004-08-03 11:50:02.000000', NULL, 1),
(839114, 94789, 19608, '<td valign="top">Interesting shapes an patterns.  Very contrasty and difficult to read.</td>', 'Interesting shapes an patterns.  Very contrasty and difficult to read.', '2004-08-03 11:50:48.000000', NULL, 1),
