(842490, 95317, 18197, '<td valign="top">Fabulous image. Very well focused and composed. Color is terrific. A ribbon candidate for sure.</td>', 'Fabulous image. Very well focused and composed. Color is terrific. A ribbon candidate for sure.', '2004-08-04 15:59:41.000000', NULL, 1),
