(844790, 94478, 7628, '<td valign="top">I very much like the novelty of your idea.  The diagonal composition is very pleasing too,  The lighting lacks a bit - too harsh at the top and right and too dark at the bottom and left.  I wish I could see more detail in the bug, and that the lighting highlighted it more.</td>', 'I very much like the novelty of your idea.  The diagonal composition is very pleasing too,  The lighting lacks a bit - too harsh at the top and right and too dark at the bottom and left.  I wish I could see more detail in the bug, and that the lighting highlighted it more.', '2004-08-05 14:57:49.000000', NULL, 1),
(844801, 95238, 7628, '<td valign="top">Being close in and filling the frame with your subject works nicely here.  I could see crpping even a bit more on top and bottom.  I''m not sure I''d really call this macro, but I do some nice details in the subject.  It would be more subtle and interesting with less harsh light - a gray day instead of bright sunshine.</td>', 'Being close in and filling the frame with your subject works nicely here.  I could see crpping even a bit more on top and bottom.  I''m not sure I''d really call this macro, but I do some nice details in the subject.  It would be more subtle and interesting with less harsh light - a gray day instead of bright sunshine.', '2004-08-05 15:00:42.000000', NULL, 1),
(844802, 94564, 22659, '<td valign="top">Nice shot. It almsost looks like it is smiling for you. Great detail and I like the texture of the tree.</td>', 'Nice shot. It almsost looks like it is smiling for you. Great detail and I like the texture of the tree.', '2004-08-05 15:01:28.000000', NULL, 1),
(844804, 95077, 22659, '<td valign="top">Great shot. I love the detail and the colour of the leaf. Cropped and titled beautifully.</td>', 'Great shot. I love the detail and the colour of the leaf. Cropped and titled beautifully.', '2004-08-05 15:03:29.000000', NULL, 1),
(844806, 95034, 7628, '<td valign="top">I like the subtle diagonal composition - the shadow in the background and the shaddoews of the dice - escecially in a subject without any straight lines!  I would prefer a plainer background - the woodgrain is a bit distracting.</td>', 'I like the subtle diagonal composition - the shadow in the background and the shaddoews of the dice - escecially in a subject without any straight lines!  I would prefer a plainer background - the woodgrain is a bit distracting.', '2004-08-05 15:03:42.000000', NULL, 1),
(844812, 95283, 22659, '<td valign="top">Nice job photographing this work of art. The water droplets make the picture. Great job.</td>', 'Nice job photographing this work of art. The water droplets make the picture. Great job.', '2004-08-05 15:06:11.000000', NULL, 1),
(844815, 94479, 7628, '<td valign="top">Interesting abstract.  Perhaps a horizontal compostion (landscape shape)  would fit the subect better - or a diagonal.  This subject would also work well in that vanishing point challenge.  I wish I could see more detail in the lights closest to the camera - texture of the plastic etc.</td>', 'Interesting abstract.  Perhaps a horizontal compostion (landscape shape)  would fit the subect better - or a diagonal.  This subject would also work well in that vanishing point challenge.  I wish I could see more detail in the lights closest to the camera - texture of the plastic etc.', '2004-08-05 15:07:57.000000', NULL, 1),
(844818, 93794, 7628, '<td valign="top">You''ve got some great detail here, and a very appropriately simple composition.  The creamy color of the center of the quill doesn''t seem quite natural - bit bright and distracting. Perhaps an entirely b&amp;W would be better. 7</td>', 'You''ve got some great detail here, and a very appropriately simple composition.  The creamy color of the center of the quill doesn''t seem quite natural - bit bright and distracting. Perhaps an entirely b&W would be better. 7', '2004-08-05 15:10:58.000000', NULL, 1),
(844819, 94473, 22975, '<td valign="top">unique idea!</td>', 'unique idea!', '2004-08-05 15:11:18.000000', NULL, 1),
(844824, 94485, 7628, '<td valign="top">I like th composition of the triangle of the watermelon poking into the frame, the single seed, and the simple white background.  The lighting could be more interesting and the focus just isn''t sharp.</td>', 'I like th composition of the triangle of the watermelon poking into the frame, the single seed, and the simple white background.  The lighting could be more interesting and the focus just isn''t sharp.', '2004-08-05 15:13:20.000000', NULL, 1),
(844826, 94233, 24715, '<td valign="top">I guess it''s a ceiling fan. Too hard to tell what it is...</td>', 'I guess it''s a ceiling fan. Too hard to tell what it is...', '2004-08-05 15:14:45.000000', NULL, 1),
(844829, 95198, 7628, '<td valign="top">Wow - nice sparks!  I like the contract in color between the neon blue of the spark and the dull metal.  Thaving your subject against the black helps focus attention on the spark, good.  The details look oversharpened or perhaps the resolution is low.</td>', 'Wow - nice sparks!  I like the contract in color between the neon blue of the spark and the dull metal.  Thaving your subject against the black helps focus attention on the spark, good.  The details look oversharpened or perhaps the resolution is low.', '2004-08-05 15:16:03.000000', NULL, 1),
(844830, 95105, 22659, '<td valign="top">I find the brownish yellowy thing in the background a little distracting. Is it a mushroom? I spent so much time tring to figure out what it was that I almost didn''t notice the blue flowers on the teeth. Maybe a little burning on that spot would have helped or is that supposed to be the main focus of the pic? hmmm....  Great choice of title and subject.</td>', 'I find the brownish yellowy thing in the background a little distracting. Is it a mushroom? I spent so much time tring to figure out what it was that I almost didn''t notice the blue flowers on the teeth. Maybe a little burning on that spot would have helped or is that supposed to be the main focus of the pic? hmmm....  Great choice of title and subject.', '2004-08-05 15:16:21.000000', NULL, 1),
(844836, 95074, 7628, '<td valign="top">Nice composition - I like the central sharply focused face and the framing of the shell and legs.  Nice colors.  I wish the light didn;t glare so off the top of the head and the shell. 6</td>', 'Nice composition - I like the central sharply focused face and the framing of the shell and legs.  Nice colors.  I wish the light didn;t glare so off the top of the head and the shell. 6', '2004-08-05 15:17:47.000000', NULL, 1),
(844841, 94047, 22659, '<td valign="top">Nice flower picture. Great detail in the pedals.</td>', 'Nice flower picture. Great detail in the pedals.', '2004-08-05 15:19:59.000000', NULL, 1),
(844843, 95158, 7628, '<td valign="top">Nice subject - some interesting textures here.  I like the colors as well.  I think you crop even more - from the top perhaps leaving only one red and one green - it would give something for the eyes to settle on.  The image is very grainy and there are some odd processing articafts - particularly in the red peppercorn - did you pump up the saturation too much?</td>', 'Nice subject - some interesting textures here.  I like the colors as well.  I think you crop even more - from the top perhaps leaving only one red and one green - it would give something for the eyes to settle on.  The image is very grainy and there are some odd processing articafts - particularly in the red peppercorn - did you pump up the saturation too much?', '2004-08-05 15:21:38.000000', NULL, 1),
(844846, 94076, 22659, '<td valign="top">Interesting choice of a macro subject. Way to think outside of the box. I like the lighting and the crop. Just not too much wow factor. Great job though. 7</td>', 'Interesting choice of a macro subject. Way to think outside of the box. I like the lighting and the crop. Just not too much wow factor. Great job though. 7', '2004-08-05 15:22:12.000000', NULL, 1),
(844856, 94390, 7628, '<td valign="top">Fun subect and set up - I like the lighting and the resulting shadow.  It tells a simple story.  Perhpas a tad more contrast? Wish the light didn''t glare so much off the bug''s back but what can you do? Very nice! 8</td>', 'Fun subect and set up - I like the lighting and the resulting shadow.  It tells a simple story.  Perhpas a tad more contrast? Wish the light didn''t glare so much off the bug''s back but what can you do? Very nice! 8', '2004-08-05 15:24:49.000000', NULL, 1),
(844860, 95167, 22659, '<td valign="top">Good macro shot. Nice cropping and perspective.</td>', 'Good macro shot. Nice cropping and perspective.', '2004-08-05 15:26:11.000000', NULL, 1),
(844862, 94037, 15207, '<td valign="top">I think this is the best composition I''ve seen so far in this macro challenge. I really love the way you balanced the shot. the colours are amazing. Also, I like that you move the eye from the bee to the background rather than having the bee look straight at you. I find it amazing that this is your first macro shot. You obv. have a knack for this. I''m giving it a 10. I wonder if people will mark you down (just subconsciously) for saying it''s your first macro though. I once put something similar in my title (I think I said unedited) and got totally burned. one guy said he marked me down for ruining my title. Hope that doesn''t happen to you. This is a ribbon shot if i ever saw one.</td>', 'I think this is the best composition I''ve seen so far in this macro challenge. I really love the way you balanced the shot. the colours are amazing. Also, I like that you move the eye from the bee to the background rather than having the bee look straight at you. I find it amazing that this is your first macro shot. You obv. have a knack for this. I''m giving it a 10. I wonder if people will mark you down (just subconsciously) for saying it''s your first macro though. I once put something similar in my title (I think I said unedited) and got totally burned. one guy said he marked me down for ruining my title. Hope that doesn''t happen to you. This is a ribbon shot if i ever saw one.', '2004-08-05 15:26:33.000000', NULL, 1),
(844863, 95132, 7628, '<td valign="top">I like how the snake''s form slithers from the corner ans the turns back to look at you - nice composition , nice for the eye to follow.  The narrow DOF works nicely too.  I wish the snake face were more in the light!  Could you dodge it in a bit more?</td>', 'I like how the snake''s form slithers from the corner ans the turns back to look at you - nice composition , nice for the eye to follow.  The narrow DOF works nicely too.  I wish the snake face were more in the light!  Could you dodge it in a bit more?', '2004-08-05 15:26:49.000000', NULL, 1),
(844868, 94235, 22659, '<td valign="top">Nice picture. It kind of looks like my signature.</td>', 'Nice picture. It kind of looks like my signature.', '2004-08-05 15:28:59.000000', NULL, 1),
(844869, 95237, 7628, '<td valign="top">Great colors!  Very good detail.  Wish the petals weren''t cropped at the edges - I''d include just a bit more. 8</td>', 'Great colors!  Very good detail.  Wish the petals weren''t cropped at the edges - I''d include just a bit more. 8', '2004-08-05 15:29:10.000000', NULL, 1),
(844872, 94624, 7628, '<td valign="top">Great colors and lighting!  I like how the colors of the flower and bug contrast so well - really makes the bug stand out.  The DOF does that too. I like the light at the top and the shadows at the bottom.  8</td>', 'Great colors and lighting!  I like how the colors of the flower and bug contrast so well - really makes the bug stand out.  The DOF does that too. I like the light at the top and the shadows at the bottom.  8', '2004-08-05 15:33:22.000000', NULL, 1),
(844880, 95232, 7628, '<td valign="top">nice portrait of a barbie - desaturated it feels nostalgic, and the interesting composition (from above) gives her personality.  Nice subtle lighting.  Nice use of DOF as well.  I might crop out that bit of hair in the corner - crop a bit off the left? 8</td>', 'nice portrait of a barbie - desaturated it feels nostalgic, and the interesting composition (from above) gives her personality.  Nice subtle lighting.  Nice use of DOF as well.  I might crop out that bit of hair in the corner - crop a bit off the left? 8', '2004-08-05 15:36:40.000000', NULL, 1),
(844882, 94386, 22659, '<td valign="top">That is one freaky looking eyeball. Good detail. Great job.</td>', 'That is one freaky looking eyeball. Good detail. Great job.', '2004-08-05 15:37:01.000000', NULL, 1),
(844884, 93789, 7628, '<td valign="top">Nice capture!  The bird is sharp and well composed.  Seems like you may already have darkened the background, but you could do it even more, and perhaps blur a bit more.  It is still a bit distracting. 8</td>', 'Nice capture!  The bird is sharp and well composed.  Seems like you may already have darkened the background, but you could do it even more, and perhaps blur a bit more.  It is still a bit distracting. 8', '2004-08-05 15:38:25.000000', NULL, 1),
(844886, 94666, 7628, '<td valign="top">lovely colors- I like the lighting against the darkness - makes the leaves look like jewels, and effect enhanced even more by the addition of the water droplets.  I''d crop a bit more on the left.  I wish it were just a bit sharper too. 7</td>', 'lovely colors- I like the lighting against the darkness - makes the leaves look like jewels, and effect enhanced even more by the addition of the water droplets.  I''d crop a bit more on the left.  I wish it were just a bit sharper too. 7', '2004-08-05 15:40:16.000000', NULL, 1),
(844887, 95232, 22659, '<td valign="top">Nice doll picture.  They should actually make Barbie dolls a challenge. I think a shot like this would do pretty well. Great job.</td>', 'Nice doll picture.  They should actually make Barbie dolls a challenge. I think a shot like this would do pretty well. Great job.', '2004-08-05 15:40:28.000000', NULL, 1),
(844889, 95201, 7628, '<td valign="top">Nice title.  Good use of DOF.  Youve got some great detail in the foreground, and the out of focus stuff in the background gives context without being distracting, The B&amp;W makes it even simpler and more elegant.  7</td>', 'Nice title.  Good use of DOF.  Youve got some great detail in the foreground, and the out of focus stuff in the background gives context without being distracting, The B&W makes it even simpler and more elegant.  7', '2004-08-05 15:42:33.000000', NULL, 1),
(844892, 95338, 7628, '<td valign="top">Your title rings true.  You''ve got some nice detail - perhaps you sharpened a bit too much tho.  I wish the central vein weren''t so burned out bright - you''ve totally lost detail there.</td>', 'Your title rings true.  You''ve got some nice detail - perhaps you sharpened a bit too much tho.  I wish the central vein weren''t so burned out bright - you''ve totally lost detail there.', '2004-08-05 15:44:54.000000', NULL, 1),
(844896, 94624, 22659, '<td valign="top">Good bee shot. He is a skinny little fellow. Maybe it could eat more and put some weight on if it didn''t keep getting disturbed by marcro photographers.  Nice job.</td>', 'Good bee shot. He is a skinny little fellow. Maybe it could eat more and put some weight on if it didn''t keep getting disturbed by marcro photographers.  Nice job.', '2004-08-05 15:48:10.000000', NULL, 1),
(844899, 95251, 22659, '<td valign="top">Definately not a typical flower shot. Great job.</td>', 'Definately not a typical flower shot. Great job.', '2004-08-05 15:50:11.000000', NULL, 1),
(844906, 95252, 22659, '<td valign="top">Very nice macro detail. Good flower shot but there are just soooo many to vote on. I hope your score doesn''t suffer because of it.</td>', 'Very nice macro detail. Good flower shot but there are just soooo many to vote on. I hope your score doesn''t suffer because of it.', '2004-08-05 15:54:21.000000', NULL, 1),
(844909, 93789, 22659, '<td valign="top">Great capture. Excellent detail. Good job.</td>', 'Great capture. Excellent detail. Good job.', '2004-08-05 15:56:33.000000', NULL, 1),
(844912, 94655, 19608, '<td valign="top">GREAT B&amp;W closeup!  The detail in the fur and the eye is spectacular.  Exposure had to be difficult with so much dark area - but you nailed it.  Having said all that - your gaudy border is absolutely terrible and should be quickly destroyed.</td>', 'GREAT B&W closeup!  The detail in the fur and the eye is spectacular.  Exposure had to be difficult with so much dark area - but you nailed it.  Having said all that - your gaudy border is absolutely terrible and should be quickly destroyed.', '2004-08-05 15:57:06.000000', NULL, 1),
(844920, 94523, 16053, '<td valign="top">Nice motive and light.</td>', 'Nice motive and light.', '2004-08-05 16:15:14.000000', NULL, 1),
(844929, 95003, 7628, '<td valign="top">Now that IS close up!  Love all the detail in those hairs.  I like the diagonal - more flower-like, and those beautiful yellow petals behind and the sharper flower center under the moth''s feet.  8</td>', 'Now that IS close up!  Love all the detail in those hairs.  I like the diagonal - more flower-like, and those beautiful yellow petals behind and the sharper flower center under the moth''s feet.  8', '2004-08-05 16:33:27.000000', NULL, 1),
(844931, 95042, 7628, '<td valign="top">A lovely abstraction of a fountain.  I wish the picture were larger.  However I cannot see how thise fits a Macro challenge.</td>', 'A lovely abstraction of a fountain.  I wish the picture were larger.  However I cannot see how thise fits a Macro challenge.', '2004-08-05 16:34:43.000000', NULL, 1),
(844937, 94980, 7628, '<td valign="top">The bark provides some great texture.  I like how you''ve composed the hole on the "thirds" line.  I wish I had some sense of scale - a familiar bug or flower perhaps - to judge the size of the subject.</td>', 'The bark provides some great texture.  I like how you''ve composed the hole on the "thirds" line.  I wish I had some sense of scale - a familiar bug or flower perhaps - to judge the size of the subject.', '2004-08-05 16:37:14.000000', NULL, 1),
(844939, 94722, 7628, '<td valign="top">What a marvelous deep green.  I also like the subtle pattern on the face of the hopper.  Nice focus.</td>', 'What a marvelous deep green.  I also like the subtle pattern on the face of the hopper.  Nice focus.', '2004-08-05 16:39:26.000000', NULL, 1),
(844946, 95168, 7628, '<td valign="top">Nice corner composition.  The details of baby''s breath and fern add a nice contract without being too distracting.  The frame is a bit fussy and distracting tho - and the focus could be a bit sharper.  Perhaps a darker background would make the rose stand out better.</td>', 'Nice corner composition.  The details of baby''s breath and fern add a nice contract without being too distracting.  The frame is a bit fussy and distracting tho - and the focus could be a bit sharper.  Perhaps a darker background would make the rose stand out better.', '2004-08-05 16:42:55.000000', NULL, 1),
(844947, 95167, 7628, '<td valign="top">Very nice - could make a great ad.  Makes the camera have the apeal of a sports car - sleek and shiny.  I like the composition - the angle and how the camera fills the frame, makes the viewer notice more about the camera than they would just holding it. 9</td>', 'Very nice - could make a great ad.  Makes the camera have the apeal of a sports car - sleek and shiny.  I like the composition - the angle and how the camera fills the frame, makes the viewer notice more about the camera than they would just holding it. 9', '2004-08-05 16:45:40.000000', NULL, 1),
(844950, 94655, 7628, '<td valign="top">I like the details in the iris and that tightly squinting pupil.  Great detail of the fur around the eye - a nice diagonal composition. A bit soft in the corners tho.  How did you get the cat to put up with the right lights, stay still, and let the camera get so close to its face?  Nicely done! 7</td>', 'I like the details in the iris and that tightly squinting pupil.  Great detail of the fur around the eye - a nice diagonal composition. A bit soft in the corners tho.  How did you get the cat to put up with the right lights, stay still, and let the camera get so close to its face?  Nicely done! 7', '2004-08-05 16:48:56.000000', NULL, 1),
(844965, 94386, 7628, '<td valign="top">Wow!  What detail in that iris!  And great colors too, like real gold.  I like the DOF and how it highlights the eye by having it sharp while everything else is soft.  I wish there were a bit more included on the right - just another 1/4 of an inch - I like the deep blue of the wrinkles and it would feel more complete. 9</td>', 'Wow!  What detail in that iris!  And great colors too, like real gold.  I like the DOF and how it highlights the eye by having it sharp while everything else is soft.  I wish there were a bit more included on the right - just another 1/4 of an inch - I like the deep blue of the wrinkles and it would feel more complete. 9', '2004-08-05 16:58:46.000000', NULL, 1),
(844970, 94394, 7628, '<td valign="top">I would be interested to see this in B&amp;W - the pistol would contrast so nicely with the darker petals. But as it that is some fabulous color, perhaps a bit too saturated?  I''d spot edit the imperfections in the  petals.</td>', 'I would be interested to see this in B&W - the pistol would contrast so nicely with the darker petals. But as it that is some fabulous color, perhaps a bit too saturated?  I''d spot edit the imperfections in the  petals.', '2004-08-05 17:01:46.000000', NULL, 1),
(844976, 94690, 7628, '<td valign="top">I really like the bold petals against the darkness.  The ant is a bit small to notice, but a nice touch.  Perhaps you could bumo the red saturation to make it stand out more?  Wish the whole flower were in focus.</td>', 'I really like the bold petals against the darkness.  The ant is a bit small to notice, but a nice touch.  Perhaps you could bumo the red saturation to make it stand out more?  Wish the whole flower were in focus.', '2004-08-05 17:03:40.000000', NULL, 1),
(844979, 94664, 7628, '<td valign="top">great colors and details - the gray wood and the diagonal grain make a super back drop, and the rust nail a perfect humerous touch with the title.  9</td>', 'great colors and details - the gray wood and the diagonal grain make a super back drop, and the rust nail a perfect humerous touch with the title.  9', '2004-08-05 17:05:05.000000', NULL, 1),
(844983, 94987, 14211, '<td valign="top">scary.......he''s looking right at you.Wish I could vote I''d give you a 10</td>', 'scary.......he''s looking right at you.Wish I could vote I''d give you a 10', '2004-08-05 17:05:23.000000', NULL, 1),
(845000, 95245, 4517, '<td valign="top">Very sharp and water drops a nice touch.</td>', 'Very sharp and water drops a nice touch.', '2004-08-05 17:09:17.000000', NULL, 1),
(845009, 95298, 4517, '<td valign="top">Very nice</td>', 'Very nice', '2004-08-05 17:11:09.000000', NULL, 1),
(845036, 93797, 4517, '<td valign="top">Incredible macro. You gotta tell what lens you used for this. 10</td>', 'Incredible macro. You gotta tell what lens you used for this. 10', '2004-08-05 17:16:00.000000', NULL, 1),
(845041, 94366, 8139, '<td valign="top">Unusual POV, i like this, good colors. A larger DOF could improve</td>', 'Unusual POV, i like this, good colors. A larger DOF could improve', '2004-08-05 17:17:19.000000', NULL, 1),
(845057, 94009, 9668, '<td valign="top">Seems a bit dark, nice rain drops, centered composition. 6</td>', 'Seems a bit dark, nice rain drops, centered composition. 6', '2004-08-05 17:21:36.000000', NULL, 1),
(845059, 95147, 8139, '<td valign="top">At first look , i tought it was a abstract paint. Great colors. powerfull picture.</td>', 'At first look , i tought it was a abstract paint. Great colors. powerfull picture.', '2004-08-05 17:21:55.000000', NULL, 1),
(845073, 95147, 9668, '<td valign="top">Nice fill the frame,  good composition, though I would like to see the entire beak. Cool colors,   sweet bird.</td>', 'Nice fill the frame,  good composition, though I would like to see the entire beak. Cool colors,   sweet bird.', '2004-08-05 17:24:55.000000', NULL, 1),
(845078, 94235, 9668, '<td valign="top">Black and white works well. Beautiful composition, one of my favorites of this challenge.</td>', 'Black and white works well. Beautiful composition, one of my favorites of this challenge.', '2004-08-05 17:26:04.000000', NULL, 1),
(845080, 95283, 24996, '<td valign="top">So cool!</td>', 'So cool!', '2004-08-05 17:26:24.000000', NULL, 1),
(845083, 94865, 9668, '<td valign="top">Different, good. Would like to see the bottom of the board inside the red box. Lighting seems a tad harsh, but minor.</td>', 'Different, good. Would like to see the bottom of the board inside the red box. Lighting seems a tad harsh, but minor.', '2004-08-05 17:28:19.000000', NULL, 1),
(845087, 95187, 10047, '<td valign="top">A bit soft on the focus.</td>', 'A bit soft on the focus.', '2004-08-05 17:31:08.000000', NULL, 1),
(845088, 93710, 9668, '<td valign="top">I''m wondering how many outtakes you had. Nice action capture, love the backdrop/lightings.</td>', 'I''m wondering how many outtakes you had. Nice action capture, love the backdrop/lightings.', '2004-08-05 17:31:23.000000', NULL, 1),
(845089, 94485, 10047, '<td valign="top">Soft on the focus. I might have tried a different background color also.</td>', 'Soft on the focus. I might have tried a different background color also.', '2004-08-05 17:32:36.000000', NULL, 1),
(845092, 94247, 9668, '<td valign="top">I don''t know what you were thinking. This isn''t macro at all. J/K.<br/>Nice dragonfly capture, seems a tad OOF</td>', 'I don''t know what you were thinking. This isn''t macro at all. J/K.Nice dragonfly capture, seems a tad OOF', '2004-08-05 17:33:49.000000', NULL, 1),
(845093, 94401, 10047, '<td valign="top">Soft on the focus, but I like the expression.</td>', 'Soft on the focus, but I like the expression.', '2004-08-05 17:33:50.000000', NULL, 1),
(845097, 94467, 10047, '<td valign="top">Looks a little overexposed, and a little soft.</td>', 'Looks a little overexposed, and a little soft.', '2004-08-05 17:35:18.000000', NULL, 1),
(845100, 94121, 10047, '<td valign="top">Looks over saturated.</td>', 'Looks over saturated.', '2004-08-05 17:37:02.000000', NULL, 1),
(845104, 95295, 10047, '<td valign="top">Would like to see this with a deeper DOF.</td>', 'Would like to see this with a deeper DOF.', '2004-08-05 17:38:30.000000', NULL, 1),
(845106, 94977, 10047, '<td valign="top">A liitle soft and washed out. The angle is good.</td>', 'A liitle soft and washed out. The angle is good.', '2004-08-05 17:40:30.000000', NULL, 1),
(845107, 94664, 10047, '<td valign="top">Excellent.  Nice clarity and color.</td>', 'Excellent.  Nice clarity and color.', '2004-08-05 17:41:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(845109, 95198, 10047, '<td valign="top">Creative with good contrast.</td>', 'Creative with good contrast.', '2004-08-05 17:41:27.000000', NULL, 1),
(845111, 94948, 10047, '<td valign="top">Well done. Crisp and clear.</td>', 'Well done. Crisp and clear.', '2004-08-05 17:41:54.000000', NULL, 1),
(845113, 94348, 10047, '<td valign="top">Excellent lighting, clarity, and detail.</td>', 'Excellent lighting, clarity, and detail.', '2004-08-05 17:42:25.000000', NULL, 1),
(845115, 94386, 10047, '<td valign="top">Excellent shot. I look forward to finding out how you got so close.</td>', 'Excellent shot. I look forward to finding out how you got so close.', '2004-08-05 17:43:20.000000', NULL, 1),
(845118, 95015, 10047, '<td valign="top">One of my favorites. Nicely done. Excellent clarity and composition.</td>', 'One of my favorites. Nicely done. Excellent clarity and composition.', '2004-08-05 17:44:09.000000', NULL, 1),
(845119, 95183, 10047, '<td valign="top">Excellent detail and clarity. Nicely done.</td>', 'Excellent detail and clarity. Nicely done.', '2004-08-05 17:44:46.000000', NULL, 1),
(845124, 94987, 10047, '<td valign="top">Excellent. Great lighting and clarity.</td>', 'Excellent. Great lighting and clarity.', '2004-08-05 17:45:57.000000', NULL, 1),
(845126, 95214, 10047, '<td valign="top">Awesome color, clarity, and detail.</td>', 'Awesome color, clarity, and detail.', '2004-08-05 17:47:05.000000', NULL, 1),
