(847947, 93659, 11738, '<td valign="top">Such a weirdly nice looking image.  You must have used some sort of PS effect right?  I would have liked to see those back hairs closer to the front a bit clearer though.  Cool effect and nice job.</td>', 'Such a weirdly nice looking image.  You must have used some sort of PS effect right?  I would have liked to see those back hairs closer to the front a bit clearer though.  Cool effect and nice job.', '2004-08-07 12:22:35.000000', NULL, 1),
(847950, 95283, 11738, '<td valign="top">Nice concept and colours, but a little too blurry for my liking.  The ultra shallow DOF caused by macro has made the water droplets fuzzy.  Too bad.</td>', 'Nice concept and colours, but a little too blurry for my liking.  The ultra shallow DOF caused by macro has made the water droplets fuzzy.  Too bad.', '2004-08-07 12:24:17.000000', NULL, 1),
(847952, 95239, 11738, '<td valign="top">Awesome minimalistic image.  The black background works wonders.  Extremely well lit too.  That thin green line also adds nicely to the image.</td>', 'Awesome minimalistic image.  The black background works wonders.  Extremely well lit too.  That thin green line also adds nicely to the image.', '2004-08-07 12:25:41.000000', NULL, 1),
(847955, 95015, 11738, '<td valign="top">Good square crop.  Too bad about that little bit of brown on that leaf tip, but excellent work nonetheless.  Lighting a tad harsh on his shell.</td>', 'Good square crop.  Too bad about that little bit of brown on that leaf tip, but excellent work nonetheless.  Lighting a tad harsh on his shell.', '2004-08-07 12:27:26.000000', NULL, 1),
