INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(850617, 95158, 7322, '<td valign="top"><b>Hi there from the Critique Club!</b> <br/> <br/>This was an interesting choice for a Macro challenge. It reveals a desire to achieve something original (oddly, I toyed with the idea of vari-colored peppercorns myself). You don''t mention what you were aiming for so I''m going to evaluate this based on the assumption that you were going for a flat, graphic quality rather than a more three-dimensional study. If this is the case, you were fairly successful. There are no distracting glares or hot-spots to interfere with the pattern created by the peppercorns. There are shadows but they are compressed and black enough to work as a sort of outline throughout the design. The white peppercorns at first seem rather distracting but a longer viewing reveals an S-shape created throughout the vertical plane accented at either end by a red and green peppercorn. This may be purely accidental but it is interesting enough to be worth noting. I have to agree with other commenters that the image is a bit grainy. I''m not convinced that it hurts this image though. It might be interesting to add even more grain and see what results. <br/> <br/>In closing, I find that although it is not an entirely successful photograph, it reveals curiousity and a desire to explore the texture, form, and color of your environment beyond the ''safe'' subjects, which is a step in the right direction. <br/> <br/>Thanks for sharing it.</td>', 'Hi there from the Critique Club!  This was an interesting choice for a Macro challenge. It reveals a desire to achieve something original (oddly, I toyed with the idea of vari-colored peppercorns myself). You don''t mention what you were aiming for so I''m going to evaluate this based on the assumption that you were going for a flat, graphic quality rather than a more three-dimensional study. If this is the case, you were fairly successful. There are no distracting glares or hot-spots to interfere with the pattern created by the peppercorns. There are shadows but they are compressed and black enough to work as a sort of outline throughout the design. The white peppercorns at first seem rather distracting but a longer viewing reveals an S-shape created throughout the vertical plane accented at either end by a red and green peppercorn. This may be purely accidental but it is interesting enough to be worth noting. I have to agree with other commenters that the image is a bit grainy. I''m not convinced that it hurts this image though. It might be interesting to add even more grain and see what results.  In closing, I find that although it is not an entirely successful photograph, it reveals curiousity and a desire to explore the texture, form, and color of your environment beyond the ''safe'' subjects, which is a step in the right direction.  Thanks for sharing it.', '2004-08-09 11:52:36.000000', NULL, 0),
(850641, 93797, 22484, '<td valign="top">O my god what a great shot !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!! end less</td>', 'O my god what a great shot !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!! end less', '2004-08-09 12:06:55.000000', NULL, 0),
(850705, 94463, 22734, '<td valign="top">A truly expert shot and very well lit with a deamatic twist, yet look at the detail of the meral keys...this is outstanding !</td>', 'A truly expert shot and very well lit with a deamatic twist, yet look at the detail of the meral keys...this is outstanding !', '2004-08-09 12:41:50.000000', NULL, 0),
(850772, 95158, 1031, '<td valign="top">I really like the crinkly texture; reminds me a little of a photo I did of some lychees. I think the brightest highlights on the white peppercorns are just a little TOO bright (for me); I had a couple of similar spots on my own Macro entry and finally went back and just barely touched them with the burn tool, and it seemed to help.<br/> <br/>Given the emphasis on the texture of the individual peppercorns, but the overall amorphous arrangement (unlike some previously-seen yin/yang presentations), I think there may be something vaguely disturbing about the portrait orientation. I probably would have cropped to a square, but I suspect you may have gotten a small bump in your score just by putting it on its side.<br/> <br/>I also want to get cute and re-title it <b>Peppercorn Salad</b> : )</td>', 'I really like the crinkly texture; reminds me a little of a photo I did of some lychees. I think the brightest highlights on the white peppercorns are just a little TOO bright (for me); I had a couple of similar spots on my own Macro entry and finally went back and just barely touched them with the burn tool, and it seemed to help. Given the emphasis on the texture of the individual peppercorns, but the overall amorphous arrangement (unlike some previously-seen yin/yang presentations), I think there may be something vaguely disturbing about the portrait orientation. I probably would have cropped to a square, but I suspect you may have gotten a small bump in your score just by putting it on its side. I also want to get cute and re-title it Peppercorn Salad : )', '2004-08-09 13:14:53.000000', NULL, 0),
(850779, 93797, 4482, '<td valign="top">OK, I need to get that 50mm inverted thing-o-magig that you used. COngrats on the double whammy!</td>', 'OK, I need to get that 50mm inverted thing-o-magig that you used. COngrats on the double whammy!', '2004-08-09 13:18:47.000000', NULL, 0),
